if (typeof document !== "undefined" && !document.getElementById("chatcn-aspect-ratio-picker")) {
  const style = document.createElement("style")
  style.id = "chatcn-aspect-ratio-picker"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

/**
 * A rectangle at the real ratio inside a square box: the ratio you see before you read it.
 * 1.5 px stroke, like the icon set.
 */
export function RatioGlyph({
  ratio,
  box = 16,
  dashed,
  className,
}: {
  ratio: number
  box?: number
  dashed?: boolean
  className?: string
}) {
  const inner = box - 3
  const min = box * 0.28
  const w = ratio >= 1 ? inner : Math.max(min, inner * ratio)
  const h = ratio >= 1 ? Math.max(min, inner / ratio) : inner
  return (
    <svg
      aria-hidden="true"
      viewBox={`0 0 ${box} ${box}`}
      width={box}
      height={box}
      data-slot="ratio-glyph"
      className={cn("shrink-0", className)}
    >
      <rect
        x={(box - w) / 2}
        y={(box - h) / 2}
        width={w}
        height={h}
        rx={box / 10}
        fill="none"
        stroke="currentColor"
        strokeWidth={1.5}
        strokeDasharray={dashed ? "2 2" : undefined}
        strokeLinecap="round"
      />
    </svg>
  )
}

/** `"16:9"` to `{ width: 16, height: 9 }`, or undefined when it cannot be read. */
export function parseAspectRatio(value: string | undefined) {
  if (!value) return undefined
  const [w, h] = value.split(":").map(Number)
  return w && h && w > 0 && h > 0 ? { width: w, height: h, ratio: w / h } : undefined
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface AspectRatioOption {
  /** `"W:H"`, for example `"16:9"`. */
  value: string
  /** Defaults to the value. */
  label?: string
  /** A word for screen readers and the popover, for example "Widescreen". */
  name?: string
  disabled?: boolean
}

const DEFAULT_OPTIONS: AspectRatioOption[] = [
  { value: "1:1", name: "Square" },
  { value: "4:5", name: "Portrait" },
  { value: "3:2", name: "Photo" },
  { value: "4:3", name: "Standard" },
  { value: "16:9", name: "Widescreen" },
  { value: "9:16", name: "Vertical" },
  { value: "21:9", name: "Cinema" },
]

export type AspectRatioPickerLayout = "inline" | "popover"

export interface AspectRatioPickerProps
  extends Omit<React.ComponentProps<"div">, "defaultValue" | "onChange" | "dir"> {
  /**
   * `"W:H"`. A preset value selects that preset; anything else is a custom size in pixels, for
   * example `"1536:1024"`.
   */
  value?: string
  /** Default `"1:1"`. */
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** Presets, as values or option objects. Defaults to 1:1, 4:5, 3:2, 4:3, 16:9, 9:16 and 21:9. */
  options?: Array<string | AspectRatioOption>
  /** Offer a custom width and height. Default true. */
  allowCustom?: boolean
  /** Bounds for custom sizes in px. Default 256 to 4096. */
  min?: number
  max?: number
  /** Custom sizes snap to a multiple of this on blur, as most models require. Default 8. */
  step?: number
  /** The size Custom starts from. Default `"1536:1024"`. */
  defaultCustom?: string
  /** `inline` is a segmented row; `popover` is a compact trigger with a grid. Default `inline`. */
  layout?: AspectRatioPickerLayout
  disabled?: boolean
  /** Names the radio group. Default "Aspect ratio". */
  label?: string
  /** Popover only. */
  open?: boolean
  onOpenChange?: (open: boolean) => void
  side?: "top" | "bottom"
  align?: "start" | "center" | "end"
}

const normalize = (options: Array<string | AspectRatioOption>) =>
  options.map((o) => (typeof o === "string" ? { value: o } : o))

const CUSTOM = "custom"

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

/**
 * A row that scrolls sideways on narrow screens: marks which edges hide options, so they fade
 * instead of cutting a glyph in half, and keeps the checked option in view.
 */
function useOverflowRow(selected: string) {
  const ref = React.useRef<HTMLDivElement>(null)
  React.useLayoutEffect(() => {
    const el = ref.current
    if (!el) return
    const update = () => {
      const start = Math.abs(el.scrollLeft)
      el.toggleAttribute("data-scroll-start", start > 1)
      el.toggleAttribute("data-scroll-end", start + el.clientWidth < el.scrollWidth - 1)
    }
    update()
    el.addEventListener("scroll", update, { passive: true })
    const observer = new ResizeObserver(update)
    observer.observe(el)
    return () => {
      el.removeEventListener("scroll", update)
      observer.disconnect()
    }
  }, [])
  React.useLayoutEffect(() => {
    void selected
    const el = ref.current
    const checked = el?.querySelector<HTMLElement>('[aria-checked="true"]')
    if (!el || !checked || el.scrollWidth <= el.clientWidth) return
    // Scroll the row only: scrollIntoView would also move the page.
    const box = el.getBoundingClientRect()
    const item = checked.getBoundingClientRect()
    const pad = 24
    if (item.left < box.left + pad) el.scrollLeft -= box.left + pad - item.left
    else if (item.right > box.right - pad) el.scrollLeft += item.right - (box.right - pad)
  }, [selected])
  return ref
}

/* -------------------------------------------------------------------------------------------------
 * Roving radio group
 * -----------------------------------------------------------------------------------------------*/

interface Choice {
  value: string
  label: string
  name?: string
  ratio: number
  disabled: boolean
  custom?: boolean
}

/** Arrow keys move and select, skipping disabled options. Grids move by row with up and down. */
function useRovingRadios(
  choices: Choice[],
  selected: string,
  select: (value: string) => void,
  columns: number,
) {
  const refs = React.useRef<Array<HTMLButtonElement | null>>([])
  const onKeyDown = (event: React.KeyboardEvent<HTMLElement>) => {
    const current = choices.findIndex((c) => c.value === selected)
    const from = Math.max(0, current)
    const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
    const delta: Record<string, number> = {
      ArrowRight: rtl ? -1 : 1,
      ArrowLeft: rtl ? 1 : -1,
      ArrowDown: columns,
      ArrowUp: -columns,
    }
    let target: number | undefined
    if (event.key === "Home") target = choices.findIndex((c) => !c.disabled)
    else if (event.key === "End") target = choices.findLastIndex((c) => !c.disabled)
    else if (event.key in delta) {
      const step = delta[event.key] ?? 0
      const n = choices.length
      let i = from
      for (let k = 0; k < n; k++) {
        i = (((i + step) % n) + n) % n
        if (!choices[i]?.disabled) break
      }
      target = i
    }
    if (target === undefined || target < 0) return
    event.preventDefault()
    const next = choices[target]
    if (!next || next.disabled) return
    select(next.value)
    refs.current[target]?.focus()
  }
  // The one tab stop: the selected option, or the first enabled one.
  const stop = choices.some((c) => c.value === selected && !c.disabled)
    ? selected
    : choices.find((c) => !c.disabled)?.value
  return { refs, onKeyDown, stop }
}

type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
  "active:scale-(--chatcn-press-scale) active:duration-100 disabled:pointer-events-none disabled:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
)

const variants: Record<ButtonVariant, string> = {
  solid: "bg-(color:--chatcn-primary) text-(color:--chatcn-primary-fg) hover:bg-(color:--chatcn-primary-hover)",
  outline: "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs) hover:bg-(color:--chatcn-fill-hover)",
  ghost: "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg)",
  subtle: "bg-(color:--chatcn-fill) text-(color:--chatcn-fg) hover:bg-(color:--chatcn-fill-hover)",
}

// Heights follow the control scale: 24, 28, 32, 36. Radii stay concentric inside 12 px surfaces.
const sizes: Record<ButtonSize, string> = {
  xs: "h-6 rounded-(--chatcn-radius-sm) px-2 text-[0.75rem]/[1rem] [&_svg]:size-3.5",
  sm: "h-7 rounded-(--chatcn-radius-sm) px-2.5 text-[0.8125rem]/[1.25rem] [&_svg]:size-3.5",
  md: "h-8 rounded-(--chatcn-radius-md) px-3 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  lg: "h-9 rounded-(--chatcn-radius-md) px-3.5 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  "icon-xs": "size-6 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-sm": "size-7 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-md": "size-8 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
  "icon-lg": "size-9 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
}

/** Class names for anything that should look like a button, such as a link. */
function buttonVariants({
  variant = "ghost",
  size = "md",
}: {
  variant?: ButtonVariant
  size?: ButtonSize
} = {}) {
  return cn(base, variants[variant], sizes[size])
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
