const UnlockIcon: Icon = /* @__PURE__ */ createIcon("unlock", iconNode2)

/* -------------------------------------------------------------------------------------------------
 * Custom size fields
 * -----------------------------------------------------------------------------------------------*/

function CustomSize({
  value,
  onChange,
  min,
  max,
  step,
  disabled,
}: {
  value: { width: number; height: number }
  onChange: (width: number, height: number) => void
  min: number
  max: number
  step: number
  disabled?: boolean
}) {
  const id = React.useId()
  const [locked, setLocked] = React.useState(false)
  const lockedRatio = React.useRef(value.width / value.height)
  const [draft, setDraft] = React.useState({
    width: String(value.width),
    height: String(value.height),
  })
  const [synced, setSynced] = React.useState(value)
  // Follow outside changes without clobbering what is being typed.
  if (synced.width !== value.width || synced.height !== value.height) {
    setSynced(value)
    setDraft({ width: String(value.width), height: String(value.height) })
  }

  const valid = (n: number) => Number.isFinite(n) && n >= min && n <= max
  const snap = (n: number) => Math.min(max, Math.max(min, Math.round(n / step) * step || min))

  const change = (axis: "width" | "height", text: string) => {
    const digits = text.replace(/[^\d]/g, "").slice(0, 5)
    const n = Number(digits)
    const next = { ...draft, [axis]: digits }
    if (locked && digits) {
      const other = axis === "width" ? n / lockedRatio.current : n * lockedRatio.current
      next[axis === "width" ? "height" : "width"] = String(Math.round(other))
    }
    setDraft(next)
    const w = Number(next.width)
    const h = Number(next.height)
    if (valid(w) && valid(h)) {
      setSynced({ width: w, height: h })
      onChange(w, h)
    }
  }

  const commit = () => {
    let w = snap(Number(draft.width) || value.width)
    let h = snap(Number(draft.height) || value.height)
    if (locked) h = snap(w / lockedRatio.current)
    if (!valid(h)) {
      h = snap(h)
      w = snap(h * lockedRatio.current)
    }
    setDraft({ width: String(w), height: String(h) })
    setSynced({ width: w, height: h })
    onChange(w, h)
  }

  const invalid = (axis: "width" | "height") => {
    const text = draft[axis]
    return text !== "" && !valid(Number(text))
  }
  const error = invalid("width") || invalid("height")

  const field = (axis: "width" | "height", label: string) => (
    <label
      className={cn(
        "bg-(color:--chatcn-card) shadow-(--chatcn-shadow-xs) rounded-(--chatcn-radius-sm) flex h-7 min-w-0 flex-1 items-center gap-1 ps-2 pe-1.5",
        "focus-within:shadow-(--chatcn-shadow-input-focus) ease-(--chatcn-ease-standard) transition-shadow duration-150",
        invalid(axis) && "shadow-[0_0_0_1px_var(--chatcn-red)]",
        disabled && "opacity-50",
      )}
    >
      <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) w-3 shrink-0">{label[0]}</span>
      <input
        type="text"
        inputMode="numeric"
        aria-label={label}
        aria-invalid={invalid(axis) || undefined}
        aria-describedby={error ? `${id}-error` : undefined}
        value={draft[axis]}
        disabled={disabled}
        onChange={(event) => change(axis, event.currentTarget.value)}
        onBlur={commit}
        onKeyDown={(event) => {
          if (event.key === "Enter" && !event.nativeEvent.isComposing) commit()
          if (event.key === "ArrowUp" || event.key === "ArrowDown") {
            event.preventDefault()
            const n = Number(draft[axis]) || value[axis]
            change(axis, String(snap(n + (event.key === "ArrowUp" ? step : -step))))
          }
        }}
        className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) min-w-0 flex-1 bg-transparent tabular-nums outline-none"
      />
      <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0">px</span>
    </label>
  )

  return (
    <div data-slot="aspect-ratio-custom" className="flex flex-col gap-1.5">
      <div className="flex items-center gap-1.5">
        {field("width", "Width")}
        <span aria-hidden="true" className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle)">
          ×
        </span>
        {field("height", "Height")}
        <button
          type="button"
          aria-pressed={locked}
          aria-label="Lock aspect ratio"
          title={locked ? "Unlock aspect ratio" : "Lock aspect ratio"}
          disabled={disabled}
          onClick={() => {
            lockedRatio.current = value.width / value.height
            setLocked((l) => !l)
          }}
          className={cn(
            buttonVariants({ variant: "ghost", size: "icon-sm" }),
            "pointer-coarse:size-11",
            locked && "bg-(color:--chatcn-fill) text-(color:--chatcn-accent) hover:text-(color:--chatcn-accent)",
          )}
        >
          <span
            key={locked ? "locked" : "open"}
            className="grid place-items-center motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]"
          >
            {locked ? <LockIcon /> : <UnlockIcon />}
          </span>
        </button>
      </div>
      {error ? (
        <p id={`${id}-error`} className="text-[0.75rem]/[1rem] text-(color:--chatcn-red)">
          Use {min} to {max} px on each side.
        </p>
      ) : null}
    </div>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Parts
 * -----------------------------------------------------------------------------------------------*/

/**
 * Root. Controlled with `open` and `onOpenChange`, or uncontrolled with `defaultOpen`.
