  const presets = normalize(options)
  const presetValues = presets.map((o) => o.value)

  const [valueState, setValueState] = React.useState(defaultValue)
  const value = valueProp ?? valueState
  const setValue = (next: string) => {
    if (valueProp === undefined) setValueState(next)
    onValueChange?.(next)
  }

  // Custom stays selected while its numbers happen to match a preset.
  const [customMode, setCustomMode] = React.useState(() => !presetValues.includes(value))
  const isCustom = allowCustom && (customMode || !presetValues.includes(value))
  const selected = isCustom ? CUSTOM : value
  const rowRef = useOverflowRow(selected)
  const lastCustom = React.useRef(isCustom ? value : defaultCustom)
  if (isCustom) lastCustom.current = value
  const customSize = parseAspectRatio(lastCustom.current) ??
    parseAspectRatio(defaultCustom) ?? { width: 1536, height: 1024 }

  const choices: Choice[] = [
    ...presets.map((o) => ({
      value: o.value,
      label: o.label ?? o.value,
      name: o.name,
      ratio: parseAspectRatio(o.value)?.ratio ?? 1,
      disabled: disabled || Boolean(o.disabled),
    })),
    ...(allowCustom
      ? [
          {
            value: CUSTOM,
            label: "Custom",
            ratio: customSize.width / customSize.height,
            disabled,
            custom: true,
          },
        ]
      : []),
  ]

  const select = (next: string) => {
    if (next === CUSTOM) {
      setCustomMode(true)
      setValue(lastCustom.current)
    } else {
      setCustomMode(false)
      setValue(next)
    }
