  const [openState, setOpenState] = React.useState(false)
  const isOpen = open ?? openState
  const setOpen = (next: boolean) => {
    if (open === undefined) setOpenState(next)
    onOpenChange?.(next)
  }

  const columns = layout === "popover" ? 4 : 1
  const roving = useRovingRadios(choices, selected, select, columns)

  const custom = isCustom ? (
    <CustomSize
      value={customSize}
      min={min}
      max={max}
      step={step}
      disabled={disabled}
      onChange={(w, h) => setValue(`${w}:${h}`)}
    />
  ) : null

  const radios = choices.map((choice, i) => {
    const checked = selected === choice.value
    return (
