        }}
        onKeyDown={(event) => {
          if (layout === "popover" && event.key === "Enter" && !choice.disabled) {
            event.preventDefault()
            select(choice.value)
            if (!choice.custom) setOpen(false)
          }
        }}
        className={cn(
          "chatcn-focus text-[0.8125rem]/[1.25rem] font-medium tabular-nums select-none",
          "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow] duration-150",
          "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-40",
          layout === "inline"
            ? cn(
                "rounded-(--chatcn-radius-sm) flex h-7 shrink-0 items-center gap-1.5 ps-1.5 pe-2.5 pointer-coarse:h-11",
                checked
                  ? "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs)"
                  : "text-(color:--chatcn-fg-muted) [@media(hover:hover)]:not-data-[disabled]:hover:text-(color:--chatcn-fg)",
              )
            : cn(
                "rounded-(--chatcn-radius-sm) flex h-15 flex-col items-center justify-center gap-1.5",
                checked
                  ? "bg-(color:--chatcn-fill-hover) text-(color:--chatcn-fg)"
                  : "text-(color:--chatcn-fg-muted) [@media(hover:hover)]:not-data-[disabled]:hover:bg-(color:--chatcn-fill) [@media(hover:hover)]:not-data-[disabled]:hover:text-(color:--chatcn-fg)",
              ),
        )}
      >
        <RatioGlyph
          ratio={choice.ratio}
          box={layout === "inline" ? 16 : 22}
          dashed={choice.custom}
          className={cn(checked && "text-(color:--chatcn-accent)")}
        />
        <span className={cn(layout === "popover" && "text-[0.75rem]/[1rem]")}>{choice.label}</span>
      </button>
    )
  })

  if (layout === "popover") {
    const current = choices.find((c) => c.value === selected)
    const triggerLabel = isCustom
      ? `${customSize.width} × ${customSize.height}`
      : (current?.label ?? value)
    return (
      <div
        data-slot="aspect-ratio-picker"
        data-layout="popover"
