              aria-hidden="true"
              className="text-(color:--chatcn-fg-subtle) ease-(--chatcn-ease-out) transition-[rotate] duration-150 in-data-[popup-open]:rotate-180"
            />
          </PopoverTrigger>
          <PopoverContent side={side} align={align} className="w-68 p-1.5">
            <PopoverTitle className="sr-only">{label}</PopoverTitle>
            <div
              role="radiogroup"
              aria-label={label}
              onKeyDown={roving.onKeyDown}
              className="grid grid-cols-4 gap-1"
            >
              {radios}
            </div>
            {custom ? (
              <div className="border-(color:--chatcn-border) mt-1.5 border-t p-1.5 pt-3">{custom}</div>
            ) : null}
          </PopoverContent>
        </Popover>
      </div>
    )
  }

  return (
    <div
      data-slot="aspect-ratio-picker"
      data-layout="inline"
      className={cn("flex max-w-full min-w-0 flex-col gap-2", className)}
      {...props}
    >
      <div
        ref={rowRef}
        role="radiogroup"
        aria-label={label}
        aria-disabled={disabled || undefined}
        onKeyDown={roving.onKeyDown}
        className={cn(
